\begin{figure}[ht!]
\centering
\resizebox{\linewidth}{!}{
\begin{tikzpicture}[
    node distance=7mm and 12mm,
    >=Latex,
    every node/.style={
        draw,
        rounded corners,
        align=center,
        font=\small,
        inner sep=5pt,
        text width=3.4cm
    },
    theorem/.style={
        draw,
        very thick,
        text width=4.0cm
    },
    arrow/.style={
        ->,
        thick
    }
]

\node (corr)
{
Lemma~\ref{lem:cubic-correlation-identity}\\
\textbf{Cubic correlation identity}\\
$\Psi_\zeta(\omega)
 = \frac1K\sum_c
 \zeta\eta_3(b_c)\rho_c^3$
};

\node (onecluster) [below left=of corr]
{
Lemma~\ref{lem:one-cluster-maxima}\\
\textbf{One-cluster landscape}\\
positive local maxima cannot
mix predictive directions
};

\node (specialmax) [below right=of corr]
{
Lemma~\ref{lem:specialized-maxima}\\
\textbf{Specialized maxima}\\
$\omega^\star
 = \tau v_c
 + O(R^{-1})$
};

\node (flow) [below=14mm of $(onecluster)!0.5!(specialmax)$]
{
Lemma~\ref{lem:positive-signed-flow}\\
\textbf{Gradient-flow convergence}\\
unstable mixed critical points
are avoided a.s.
};

\node (selfsign) [below=of flow]
{
Lemma~\ref{lem:self-selected-specialization}\\
\textbf{Self-selected sign}\\
teacher-only dynamics select a sign
and specialize a.s.
};

\node (coverage) [below left=of selfsign]
{
Lemma~\ref{lem:uniform-cluster-coverage}\\
\textbf{Uniform labels and coverage}\\
$J_j \stackrel{\mathrm{iid}}{\sim}
\operatorname{Unif}([K])$
};

\node (tracking) [below right=of selfsign]
{
Lemma~\ref{lem:early-time-tracking}\\
\textbf{Full-network tracking}\\
coupled dynamics differ from
teacher-only dynamics by
$O(m\varepsilon^2)$
};

\node[theorem] (thm) [below=15mm of $(coverage)!0.5!(tracking)$]
{
Theorem~\ref{thm:neurons-specialize}\\
\textbf{Randomly initialized neurons specialize}\\[2pt]
$\displaystyle
\frac{w_j(T_\delta)}
     {\|w_j(T_\delta)\|_2}
\approx
\tau_j v_{J_j}$
};

\draw[arrow] (corr) -- (onecluster);
\draw[arrow] (corr) -- (specialmax);
\draw[arrow] (onecluster) -- (flow);
\draw[arrow] (specialmax) -- (flow);
\draw[arrow] (flow) -- (selfsign);
\draw[arrow] (selfsign) -- (coverage);
\draw[arrow] (selfsign) -- (tracking);
\draw[arrow, dashed]
    (corr.east)
    .. controls +(3.0,0) and +(2.5,1.0) ..
    (tracking.east);
\draw[arrow] (coverage) -- (thm);
\draw[arrow] (tracking) -- (thm);
\draw[arrow] (selfsign) -- (thm);
\draw[arrow] (specialmax)
    .. controls +(0,-2.0) and +(2.0,1.0) ..
    (thm.east);

\end{tikzpicture}
}
\caption{
Dependency graph for the proof of
Theorem~\ref{thm:neurons-specialize}.
Solid arrows indicate the main logical dependencies.
The dashed arrow records that
Lemma~\ref{lem:cubic-correlation-identity}
is also used to establish smoothness of the teacher-only
vector field in the tracking argument.
}
\label{fig:theorem1-dependencies}
\end{figure}

